+    /// <summary>Inspect animated source cells without decoding or allocating pixels.</summary>
+    public bool TryGetCellAnimation(int cellIndex, out CellAnimation animation)
+    {
+        if ((uint)cellIndex >= (uint)_overlays.BaseOverlayFlags.Length)
+            throw new ArgumentOutOfRangeException(nameof(cellIndex));
+        var flags = _overlays.BaseOverlayFlags[cellIndex];
+        for (var slot = 1; slot < 8; slot++)
+        {
+            if ((flags & (1 << slot)) == 0) continue;
+            var overlay = _slots[slot];
+            if (overlay.Columns != 1 || overlay.Rows != 1)
+                throw new NotSupportedException(
+                    $"WED overlay slot {slot} has unsupported {overlay.Columns}x{overlay.Rows} water tile placement.");
+            var cell = overlay.Cells[0];
+            animation = new CellAnimation(slot, cell.Frames.Length, cell.AnimationSpeed);
+            return true;
+        }
+        animation = default;
+        return false;
+    }

